#include "cpp_package_boilerplate/package.hpp"
#include "cpp_package_boilerplate/version.hpp"

#include <cstddef>
#include <iostream>
#include <ranges>
#include <span>
#include <string_view>

/**
 * @brief Example CLI entry point for the template package.
 *
 * This binary demonstrates how an application can consume the library API.
 * It prints a greeting generated by `cpp_package_boilerplate::greet`, or the
 * package version when invoked with `--version`.
 *
 * @return Exit status code. Returns `0` on success.
 */
auto main(int argc, char** argv) -> int {
    const std::span arguments(argv, static_cast<std::size_t>(argc));

    for (const std::string_view argument : arguments | std::views::drop(1)) {
        if (argument == "--version") {
            std::cout << cpp_package_boilerplate::version << '\n';
            return 0;
        }
    }

    std::cout << cpp_package_boilerplate::greet("world") << '\n';
    return 0;
}
